// main.ts
var CreateExcalidrawModal = class extends import_obsidian2.Modal {
  constructor(app, defaultName, onSubmit) {
    super(app);
    this.result = defaultName;
    this.onSubmit = onSubmit;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.createEl("h2", { text: "\u65B0\u898FExcalidraw\u30D5\u30A1\u30A4\u30EB\u540D" });
    new import_obsidian2.Setting(contentEl).setName("\u30D5\u30A1\u30A4\u30EB\u540D").setDesc("\u62E1\u5F35\u5B50\uFF08.excalidraw.md\uFF09\u306F\u81EA\u52D5\u7684\u306B\u8FFD\u52A0\u3055\u308C\u307E\u3059").addText((text) => {
      text.setValue(this.result);
      text.onChange((value) => {
        this.result = value;
      });
      text.inputEl.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
          if (e.isComposing)
            return;
          e.preventDefault();
          this.close();
          if (this.result) {
            this.onSubmit(this.result);
          }
        }
      });
      setTimeout(() => {
        text.inputEl.focus();
        text.inputEl.select();
      }, 50);
    });
    new import_obsidian2.Setting(contentEl).addButton(
      (btn) => btn.setButtonText("\u4F5C\u6210").setCta().onClick(() => {
        this.close();
        if (this.result) {
          this.onSubmit(this.result);
        }
      })
    );
  }
  onClose() {
    const { contentEl } = this;
    contentEl.empty();
  }
};
